/**
 * Retry starts a task over from a clean slate:
 * - the spec dir goes back to what TASK_CREATE wrote (task_metadata.json, attachments/,
 *   a fresh implementation_plan.json); everything generated by runs is removed
 * - the task's worktree and branch are discarded, so the next start branches from the base again
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, readdirSync, existsSync, rmSync } from 'fs';
import { execFileSync } from 'child_process';
import os from 'os';
import path from 'path';

vi.mock('../../../project-store', () => ({
  projectStore: { invalidateTasksCache: vi.fn() }
}));
vi.mock('../../../cli-tool-manager', () => ({
  getToolPath: () => 'git'
}));

import { resetSpecDirToInitialState } from '../plan-file-utils';
import { discardTaskWorktree } from '../../../utils/worktree-cleanup';
import { getIsolatedGitEnv } from '../../../utils/git-isolation';
import { createOrGetWorktree } from '../../../worktree';

let tmp: string;

beforeEach(() => {
  tmp = mkdtempSync(path.join(os.tmpdir(), 'task-retry-'));
  vi.spyOn(console, 'warn').mockImplementation(() => undefined);
});

afterEach(() => {
  vi.restoreAllMocks();
  rmSync(tmp, { recursive: true, force: true });
});

describe('resetSpecDirToInitialState', () => {
  it('keeps task metadata and attachments, resets the plan and removes generated files', async () => {
    const specDir = path.join(tmp, '001-feature');
    mkdirSync(path.join(specDir, 'attachments'), { recursive: true });
    mkdirSync(path.join(specDir, 'feedback_images'), { recursive: true });
    mkdirSync(path.join(specDir, 'memory'), { recursive: true });
    mkdirSync(path.join(specDir, 'logs'), { recursive: true });

    const metadata = { userDescription: 'Add a button', attachedImages: [{ path: 'attachments/a.png' }], mcpConnectors: ['context7'] };
    writeFileSync(path.join(specDir, 'task_metadata.json'), JSON.stringify(metadata));
    writeFileSync(path.join(specDir, 'attachments', 'a.png'), 'png');
    writeFileSync(path.join(specDir, 'feedback_images', 'b.png'), 'png');
    writeFileSync(path.join(specDir, 'memory', 'notes.md'), 'x');
    writeFileSync(path.join(specDir, 'logs', 'session.log'), 'x');
    writeFileSync(path.join(specDir, 'implementation_plan.json'), JSON.stringify({
      feature: 'Old title',
      description: 'old',
      created_at: '2026-01-01T00:00:00.000Z',
      updated_at: '2026-01-02T00:00:00.000Z',
      status: 'error',
      xstateState: 'error',
      executionPhase: 'failed',
      reviewReason: 'errors',
      rateLimitHold: { resetAt: 'x' },
      phases: [{ phase: 1, name: 'Claude Code task list', subtasks: [{ id: '1', status: 'completed' }] }]
    }));
    for (const file of [
      'claude_run.json', 'task_logs.json', 'plan.md', 'QA_FIX_REQUEST.md', 'qa_report.md',
      'spec.md', 'requirements.json', 'context.json', 'complexity_assessment.json',
      'project_index.json', 'build-progress.txt', 'research.json', 'implementation_plan.json.tmp'
    ]) {
      writeFileSync(path.join(specDir, file), '{}');
    }

    await resetSpecDirToInitialState(specDir, { title: 'Add a button', description: 'Add a button' });

    expect(readdirSync(specDir).sort()).toEqual(['attachments', 'implementation_plan.json', 'task_metadata.json']);
    expect(readdirSync(path.join(specDir, 'attachments'))).toEqual(['a.png']);
    expect(JSON.parse(readFileSync(path.join(specDir, 'task_metadata.json'), 'utf-8'))).toEqual(metadata);

    const plan = JSON.parse(readFileSync(path.join(specDir, 'implementation_plan.json'), 'utf-8'));
    expect(plan).toEqual({
      feature: 'Add a button',
      description: 'Add a button',
      created_at: '2026-01-01T00:00:00.000Z',
      updated_at: expect.any(String),
      status: 'pending',
      phases: []
    });
    expect(plan.updated_at).not.toBe('2026-01-02T00:00:00.000Z');
  });

  it('writes the plan queued when asked, and creates it when missing', async () => {
    const specDir = path.join(tmp, '002-feature');
    mkdirSync(specDir);
    writeFileSync(path.join(specDir, 'task_metadata.json'), '{}');

    await resetSpecDirToInitialState(specDir, { title: 'T' }, { status: 'queue' });

    const plan = JSON.parse(readFileSync(path.join(specDir, 'implementation_plan.json'), 'utf-8'));
    expect(plan).toMatchObject({ feature: 'T', description: '', status: 'queue', planStatus: 'queued', phases: [] });
    expect(typeof plan.created_at).toBe('string');
  });
});

describe('discardTaskWorktree', () => {
  const git = (cwd: string, ...args: string[]) =>
    execFileSync('git', args, { cwd, encoding: 'utf-8', env: getIsolatedGitEnv() }).trim();

  const initRepo = (): string => {
    const repo = path.join(tmp, 'repo');
    mkdirSync(repo);
    git(repo, 'init', '-q', '-b', 'main');
    git(repo, 'config', 'user.email', 'test@example.com');
    git(repo, 'config', 'user.name', 'Test');
    git(repo, 'config', 'commit.gpgsign', 'false');
    // Keep README.md's line endings as written (Windows checks out CRLF by default)
    git(repo, 'config', 'core.autocrlf', 'false');
    writeFileSync(path.join(repo, '.gitignore'), '.auto-claude/\n');
    writeFileSync(path.join(repo, 'README.md'), 'base\n');
    git(repo, 'add', '.');
    git(repo, 'commit', '-q', '-m', 'base');
    return repo;
  };

  it('removes the worktree with its commits and changes; the next start branches from the base', async () => {
    const repo = initRepo();
    const specId = '001-feature';
    const branch = `auto-claude/${specId}`;

    const first = await createOrGetWorktree(repo, specId, 'main', true, false);
    writeFileSync(path.join(first.worktreePath, 'feature.ts'), 'export const x = 1;\n');
    git(first.worktreePath, 'add', '.');
    git(first.worktreePath, 'commit', '-q', '-m', 'task work');
    writeFileSync(path.join(first.worktreePath, 'README.md'), 'uncommitted\n');
    writeFileSync(path.join(first.worktreePath, 'untracked.txt'), 'x');

    const result = await discardTaskWorktree(repo, specId, '[test]');

    expect(result.success).toBe(true);
    expect(existsSync(first.worktreePath)).toBe(false);
    expect(git(repo, 'branch', '--list', branch)).toBe('');

    const second = await createOrGetWorktree(repo, specId, 'main', true, false);
    expect(git(second.worktreePath, 'rev-parse', 'HEAD')).toBe(git(repo, 'rev-parse', 'main'));
    expect(existsSync(path.join(second.worktreePath, 'feature.ts'))).toBe(false);
    expect(existsSync(path.join(second.worktreePath, 'untracked.txt'))).toBe(false);
    expect(readFileSync(path.join(second.worktreePath, 'README.md'), 'utf-8')).toBe('base\n');
  });

  it('deletes a task branch left behind without a worktree', async () => {
    const repo = initRepo();
    const specId = '002-feature';
    git(repo, 'branch', `auto-claude/${specId}`);

    const result = await discardTaskWorktree(repo, specId, '[test]');

    expect(result.success).toBe(true);
    expect(git(repo, 'branch', '--list', `auto-claude/${specId}`)).toBe('');
  });
});
